// Regression: POST /checkout returned 500 for prices with thousands separators
// (e.g. "1,299.00") because parseAmount dereferenced a null regex match.
const assert = require('assert');
const { parseAmount } = require('../src/money');
const { checkout } = require('../src/checkout');
const { handle } = require('../src/server');

test('parses amounts with thousands separators', () => {
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,005.99'), 100599);
  assert.strictEqual(parseAmount('1,000,000'), 100000000);
});

test('rejects malformed amounts with a descriptive error', () => {
  for (const bad of ['abc', '', '1,29.00', '12,34', '1.234', ',100']) {
    assert.throws(() => parseAmount(bad), /Invalid amount/, `expected "${bad}" to be rejected`);
  }
});

test('checkout totals items priced with thousands separators', () => {
  const order = { id: 'o2', items: [{ sku: 'TV', price: '1,299.00', qty: 2 }, { sku: 'C', price: '0.50', qty: 1 }] };
  assert.deepStrictEqual(checkout(order), { orderId: 'o2', totalCents: 259850 });
});

test('POST /checkout returns 200 for comma-formatted prices', () => {
  const log = console.log;
  console.log = () => {};
  try {
    const res = handle({ method: 'POST', path: '/checkout', body: { id: 'o3', items: [{ sku: 'X', price: '2,450.50', qty: 1 }] } });
    assert.strictEqual(res.status, 200);
    assert.strictEqual(res.body.totalCents, 245050);
  } finally {
    console.log = log;
  }
});

